=== config.toml ===
[keys]
# Herdr's built-in edit_scrollback (prefix+e) hijacks the focused pane: it dumps
# that pane's scrollback to /tmp and replaces its process with $EDITOR (vi).
# Bound to a Notes pane it destroys the note pane. Disabled here; prefix+e is
# re-bound below to actually edit the workspace note.
edit_scrollback = ""

[[keys.command]]
key = "prefix+m"
type = "plugin_action"
command = "herdr-notes.toggle"
description = "Toggle workspace notes"

[[keys.command]]
key = "prefix+e"
type = "plugin_action"
command = "herdr-notes.edit"
description = "Edit workspace note in editor"

[[keys.command]]
key = "prefix+shift+m"
type = "plugin_action"
command = "herdr-notes.edit"
description = "Edit workspace note in editor"

